export const getGetUserUrl = (userId: string) => {
  return `/api/v1/users/${userId}`;
};

/**
 * Return a user the caller is allowed to see.
 *
 * Admins can see anyone; guardians their linked students; others only
 * themselves. Anything else is reported as not found.
 * @summary Get User
 */
export const getUser = async (
  userId: string,
  options?: Parameters<typeof apiFetch>[1],
): Promise<UserOut> => {
  return apiFetch<UserOut>(getGetUserUrl(userId), {
    ...options,
    method: "GET",

    schema: UserOut,
  });
};

export const getGetUserQueryKey = (userId: string) => {
  return [`/api/v1/users/${userId}`] as const;
};

export const getGetUserQueryOptions = <
  TData = Awaited<ReturnType<typeof getUser>>,
  TError = ErrorType<ErrorResponse>,
>(
  userId: string,
  options?: {
    query?: Partial<UseQueryOptions<Awaited<ReturnType<typeof getUser>>, TError, TData>>;
    request?: SecondParameter<typeof apiFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetUserQueryKey(userId);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getUser>>> = ({ signal }) =>
    getUser(userId, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: userId !== null && userId !== undefined,
    ...queryOptions,
  } as UseQueryOptions<Awaited<ReturnType<typeof getUser>>, TError, TData> & {
    queryKey: DataTag<QueryKey, TData, TError>;
  };
};

